fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn walk(p:&Path,out:&mut Vec<PathBuf>){for e in fs::read_dir(p).unwrap(){let e=e.unwrap();if e.file_type().unwrap().is_dir(){walk(&e.path(),out)}else if e.file_type().unwrap().is_file(){out.push(e.path())}}}
fn contexts()->Vec<(String,String,usize,usize)>{let mut out=vec![];for(kind,n)in[("G2",200),("G2",352),("G1",200)]{for w in[1,16,32]{out.push((format!("{kind}-{n}-w{w}"),kind.into(),n,w));}}out}
