 steps.push(step("preflight-check".into(),vec![r("campaign").display().to_string(),"preflight".into()]));
 for b in 0..15{let mut order=(0..cs.len()).collect::<Vec<_>>();order.rotate_left(b%cs.len());if b%2==1{order.reverse();}for i in order{let c=&cs[i];let mut arms=["frozen","OFF","ON"];arms.rotate_left((b+i)%3);if b%2==1{arms.reverse();}for arm in arms{steps.push(step(format!("latency-{}-b{b:02}-{arm}",c.0),args(c,arm,4096)));}}}
