 for profile in[false,true]{for c in&selected{for arm in["frozen","OFF","ON"]{
  let name=format!("{}-{}-{arm}",if profile{"cycles"}else{"stat"},c.0);let mut penv=env.clone();penv["ZOPRO_BENCH_PERF_CTL"]=json!(r("ctl"));penv["ZOPRO_BENCH_PERF_ACK"]=json!(r("ack"));
  let mut argv=vec!["sudo".into(),"-n".into(),"env".into()];for(k,v)in penv.as_object().unwrap(){argv.push(format!("{k}={}",v.as_str().unwrap()));}argv.push("perf".into());
  if profile{argv.extend(["record".into(),"--no-buildid-cache".into(),"--sample-cpu".into(),"--timestamp".into(),"-P".into(),"-e".into(),"cycles:u".into(),"-c".into(),"16000000".into(),"-m".into(),"512".into(),"-o".into(),format!("{R}/perf/{name}.data")]);}else{argv.extend(["stat".into(),"--no-big-num".into(),"-x".into(),";".into(),"-e".into(),"{cycles:u,instructions:u,cache-misses:u,branch-misses:u}".into(),"-o".into(),format!("{R}/stat/{name}.csv")]);}
  argv.extend(["--delay=-1".into(),format!("--control=fifo:{R}/ctl,{R}/ack"),"--".into()]);argv.extend(args(c,arm,if profile{65536}else{16384}));let mut s=step(name,argv);s["environment"]=penv;steps.push(s);
 }}}
